 "<b style=\"font-size:26px;color:#6c4fd0\">Funciona</b><br><span style=\"font-size:21px;color:#13302a\">En el rango de 1 a 25 µM.</span>": "<b style=\"font-size:26px;color:#6c4fd0\">Funciona</b><br><span style=\"font-size:21px;color:#13302a\">En el rang d'1 a 25 µM.</span>",
 "<b style=\"font-size:26px;color:#cb7c28\">Falta</b><br><span style=\"font-size:21px;color:#13302a\">Mejor selectividad y validación en campo.</span>": "<b style=\"font-size:26px;color:#cb7c28\">Falta</b><br><span style=\"font-size:21px;color:#13302a\">Millor selectivitat i validació al camp.</span>",
